const test=require('node:test'),assert=require('node:assert/strict');
test('motion has exact endpoints, bounded overshoot and finite staggered completion',async()=>{const {spring,motionSample,motionDefaults:s}=await import('../tile-motion.js');assert.equal(spring(0),0);assert.equal(spring(1),1);let peak=0;for(let i=0;i<=1000;i++){const v=spring(i/1000);assert(Number.isFinite(v));peak=Math.max(peak,v);}assert(peak>1&&peak<1.25);for(let i=0;i<100;i++){const v=motionSample(s.hold+s.stagger+s.duration,s,i,100);assert.equal(v.progress,1);assert.equal(v.hover,0);assert.equal(v.wobble,0);assert.equal(v.done,true);}assert.equal(motionSample(0,s).progress,0);assert.equal(motionSample(0,s).hover,0);});
